pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use any ERC20 token address - we just need the call to succeed
        address token = address(0x123);
        address from = address(0x456);
        address to = address(0x789);
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory values = new uint[](1);
        values[0] = 100;

