pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup a token contract that will fail transferFrom
        address badToken = address(0xdead);
        // Prepare arrays: two addresses, second call will fail (no code at badToken)
        address[] memory tos = new address[](2);
        tos[0] = address(0x123);
        tos[1] = address(0x456);
        uint[] memory vals = new uint[](2);
        vals[0] = 1;
        vals[1] = 2;

        // Try to call transfer - reference will revert on second call (badToken has no code)
        bool ok;
        try c.transfer(address(this), badToken, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok = false), buggy returns true (ok = true)
        // This assertion passes on reference (false) and fails on buggy (true)
        assertTrue(!ok);
    }
}

