// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token that reverts on transferFrom
        address token = address(new TokenThatReverts());
        address from = address(0x123);
        address[] memory tos = new address[](2);
        tos[0] = address(0x456);
        tos[1] = address(0x789);
        uint[] memory vals = new uint[](2);
        vals[0] = 100;
        vals[1] = 200;
        bool ok;
        try c.transfer(from, token, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference reverts (ok = false), the buggy contract does not revert (ok = true)
        assertTrue(ok == false, "Bug: transfer did not revert");
    }
}

contract TokenThatReverts {
    function transferFrom(address, address, uint) public pure returns (bool) {
        revert("fail");
    }
}
